#!/usr/bin/env bash
# CloudShell (ap-south-1). Read-only status of the live deployments; runs the
# query inside the backend container (no psql/SSL dependency).
#
#   ./status_v1.sh   → read-only health check of the live deployments
#
# READ-ONLY: no INSERT/UPDATE/DELETE anywhere, no snapshot, nothing restarted.
set -euo pipefail

MODE="${1:-inventory}"; EXTRA="${2:-}"; EXTRA2="${3:-}"
REGION=ap-south-1
APP_INSTANCE=i-09888f3320763000f
DB_ID=srtrend-production-database-xwpbny18v09d
STAMP=$(date -u +%Y%m%d%H%M%S)
PAYLOAD=''

echo "### fixparams_v1 (restore base_params statics) ###"


echo "== running on app EC2 via SSM ($MODE) =="
CMD_ID="$(aws ssm send-command --region "$REGION" \
  --instance-ids "$APP_INSTANCE" \
  --document-name AWS-RunShellScript \
  --comment "status v1 $MODE $STAMP" \
  --timeout-seconds 900 \
  --parameters "{\"commands\":[\"set -euo pipefail\",\"echo '$PAYLOAD' | base64 -d > /tmp/rf.sh\",\"chmod +x /tmp/rf.sh\",\"/tmp/rf.sh $MODE\",\"rm -f /tmp/rf.sh\"],\"executionTimeout\":[\"900\"]}" \
  --query 'Command.CommandId' --output text)"
echo "ssm command: $CMD_ID"

STATUS=InProgress
while [ "$STATUS" = InProgress ] || [ "$STATUS" = Pending ] || [ "$STATUS" = Delayed ]; do
  sleep 10
  STATUS="$(aws ssm get-command-invocation --region "$REGION" \
    --command-id "$CMD_ID" --instance-id "$APP_INSTANCE" \
    --query 'Status' --output text 2>/dev/null || echo InProgress)"
  echo "  $(date -u +%H:%M:%S) $STATUS"
done

echo "== output ($STATUS) =="
aws ssm get-command-invocation --region "$REGION" \
  --command-id "$CMD_ID" --instance-id "$APP_INSTANCE" \
  --query 'StandardOutputContent' --output text
if [ "$STATUS" != Success ]; then
  echo "== stderr =="
  aws ssm get-command-invocation --region "$REGION" \
    --command-id "$CMD_ID" --instance-id "$APP_INSTANCE" \
    --query 'StandardErrorContent' --output text | tail -30
  exit 1
fi
